def test_viafree_real_extract_converts_http_403_to_geo_restriction(monkeypatch):
    class FakeHTTPError(Exception):
        def __init__(self, code):
            super().__init__("HTTP error %d" % code)
            self.code = code

    class GeoRestrictionRaised(Exception):
        pass

    ie = tvplay.ViafreeIE()
    content = _content()
    calls = []
    geo_calls = []

    def fake_download_json(url, video_id, **kwargs):
        calls.append((url, video_id, kwargs))
        if len(calls) == 1:
            return content
        raise ExtractorError(
            "Forbidden",
            cause=FakeHTTPError(403),
        )

    def fake_raise_geo_restricted(msg="unused", countries=None):
        geo_calls.append(countries)
        raise GeoRestrictionRaised()

    monkeypatch.setattr(tvplay, "compat_HTTPError", FakeHTTPError)
    monkeypatch.setattr(ie, "_download_json", fake_download_json)
    monkeypatch.setattr(ie, "geo_verification_headers", lambda: {"Geo": "header"})
    monkeypatch.setattr(ie, "raise_geo_restricted", fake_raise_geo_restricted)

    with pytest.raises(GeoRestrictionRaised):
        ie._real_extract(
            "https://viafree.dk/programmer/category/geo-blocked-show"
        )

    assert geo_calls == [["dk"]]
    assert calls[1] == (
        "https://api.example.test/stream/guid-123",
        "guid-123",
        {"headers": {"Geo": "header"}},
    )


